<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; requireLogin();
$s=$pdo->prepare('SELECT k.jumlah_produk jumlah,p.nama,p.harga FROM keranjang k JOIN produk p ON p.id_produk=k.id_produk WHERE k.id_user=:user ORDER BY k.id_keranjang');$s->execute(['user'=>$_SESSION['id_user']]);$items=$s->fetchAll();if(!$items)redirect('cart.php');$subtotal=0;foreach($items as $item)$subtotal+=(int)$item['jumlah']*(int)$item['harga'];$ongkir=shippingCost($subtotal);$total=$subtotal+$ongkir;
$pageTitle='Checkout | MyBuah';require __DIR__.'/includes/header.php';?><section class="container page-shell section"><div class="breadcrumb">Katalog / Keranjang / Checkout</div><h1>Alamat Pengiriman</h1><div class="checkout-layout"><form class="checkout-card" action="proses_checkout.php" method="post"><h2>Data Penerima</h2><label class="form-field">Nama Penerima<input name="nama_penerima" value="<?=e(currentUserName())?>" required></label><label class="form-field">No. Telepon<input name="no_telepon" required></label><label class="form-field">Alamat Lengkap<textarea name="alamat" required></textarea></label><label class="form-field">Catatan opsional<textarea name="catatan" placeholder="mis. patokan rumah, jam pengiriman"></textarea></label><button class="button" style="background:var(--orange);color:#fff" type="submit">Lanjut ke Pembayaran →</button></form><aside class="summary-card"><h2>Ringkasan Pesanan</h2><?php foreach($items as $item):?><div class="summary-row"><span><?=e($item['nama'])?> x <?= (int)$item['jumlah']?></span><strong><?=formatRupiah($item['harga']*$item['jumlah'])?></strong></div><?php endforeach;?><div class="summary-row"><span>Subtotal</span><strong><?=formatRupiah($subtotal)?></strong></div><div class="summary-row"><span>Ongkos Kirim</span><strong><?=$ongkir?formatRupiah($ongkir):'Gratis'?></strong></div><div class="summary-total"><span>Total</span><strong><?=formatRupiah($total)?></strong></div></aside></div></section><?php require __DIR__.'/includes/footer.php';